using System.Text.Json;
using SimplePZMapmaker.Core;
using SimplePZMapmaker.Web.Services;
public static class GeographicEvidenceTests
{
 public static IEnumerable<(string,Action)> Cases(){
  yield return("geographic site membership survives source reorder and source label corrections",()=>{
   var a=new{type="Feature",id="a",properties=new Dictionary<string,string>{{"building","house"}},geometry=new{type="Polygon",coordinates=new[]{new[]{new[]{32.002,54.002},new[]{32.003,54.002},new[]{32.003,54.003},new[]{32.002,54.003},new[]{32.002,54.002}}}}};
   var b=new{type="Feature",id="b",properties=new Dictionary<string,string>{{"building","house"}},geometry=new{type="Polygon",coordinates=new[]{new[]{new[]{32.006,54.006},new[]{32.007,54.006},new[]{32.007,54.007},new[]{32.006,54.007},new[]{32.006,54.006}}}}};
   var data=JsonSerializer.Serialize(new{type="FeatureCollection",features=new[]{a,b}});var p=GeographicImporter.Import(data,MapGenerator.Generate(new(){Kind="blank"}),new(){West=32,East=32.01,South=54,North=54.01}).Project;
   p.Sites=[new(){Id="manual",Name="Keep membership",BuildingIds=p.Buildings.Select(b=>b.Id).ToList(),Boundary=[[new(1,1),new(254,1),new(254,254),new(1,254)]]}];
   a.properties["name"]="Corrected source name";var next=GeographicImporter.Import(JsonSerializer.Serialize(new{type="FeatureCollection",features=new[]{b,a}}),p,p.Bounds,preserveEdits:true).Project;
   Check(next.Sites.Single().BuildingIds.Count==2&&next.Sites.Single().BuildingIds.All(id=>next.Buildings.Any(b=>b.Id==id)),"Site members lost after reordered source");
   Check(p.SourceFeatures.Single(f=>f.SourceId=="geo-a").Id==next.SourceFeatures.Single(f=>f.SourceId=="geo-a").Id,"Source label correction changed stable evidence identity");
  });
  yield return("source area association checks original sub-tile boundaries and quantized footprint",()=>{
   var reference=new WorldGeoReference{Bounds=new(){West=32,East=32.01,South=54,North=54.01},MetresPerTile=1,OriginCellX=100,OriginCellY=100};var projection=new GeographicProjection(reference,100,100);
   object Feature(string id,string kind,double minX,double maxX,double minY,double maxY){var coords=new[]{(minX,minY),(maxX,minY),(maxX,maxY),(minX,maxY),(minX,minY)}.Select(v=>{var g=projection.Geographic(v.Item1,v.Item2);return new[]{g.Longitude,g.Latitude};}).ToArray();return new{type="Feature",id,properties=new Dictionary<string,string>{{kind,kind=="building"?"house":"school"}},geometry=new{type="Polygon",coordinates=new[]{coords}}};}
   var house=Feature("b","building",30.6,40.4,30.6,40.4);
   MapProject Import(double siteMin)=>GeographicImporter.Import(JsonSerializer.Serialize(new{type="FeatureCollection",features=new[]{house,Feature("campus","amenity",siteMin,50,25,50)}}),MapGenerator.Generate(new(){Kind="blank"}),reference.Bounds,projection:projection).Project;
   var crossing=Import(31);Check(crossing.Buildings.Count==1&&crossing.Sites.Single().BuildingIds.Count==0&&crossing.Sites.Single().AssociationNotes.Count>0,"Sub-tile crossing wrongly grouped");
   var contained=Import(30.6);Check(contained.Sites.Single().BuildingIds.Count==1,"Allocation rectangle incorrectly excluded a contained source footprint");
  });
  yield return("GeoJSON without feature IDs keeps distinct original outlines and links buildings",()=>{const string json="""{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"building":"house"},"geometry":{"type":"Polygon","coordinates":[[[32.002,54.002],[32.003,54.002],[32.003,54.003],[32.002,54.003],[32.002,54.002]]]}},{"type":"Feature","properties":{"building":"house"},"geometry":{"type":"Polygon","coordinates":[[[32.006,54.006],[32.007,54.006],[32.007,54.007],[32.006,54.007],[32.006,54.006]]]}}]}""";var p=GeographicImporter.Import(json,MapGenerator.Generate(new(){Kind="blank"}),new(){West=32,East=32.01,South=54,North=54.01}).Project;Check(p.SourceFeatures.Count==2&&p.Buildings.Count==2,"Unidentified source geometries collapsed");Check(p.SourceFeatures.All(e=>e.BuildingId is not null)&&p.SourceFeatures.Select(e=>e.SourceId).Distinct().Count()==2,"Anonymous evidence not linked");var next=GeographicImporter.Import(json,p,p.Bounds).Project;Check(p.SourceFeatures.Select(e=>e.Id).SequenceEqual(next.SourceFeatures.Select(e=>e.Id)),"Fallback IDs are unstable");});

  yield return("source point-only imports preserve real services and original coordinates",()=>{var p=GeographicImporter.Import("""{"type":"FeatureCollection","features":[{"type":"Feature","id":"clinic","properties":{"amenity":"clinic","name":"Survey clinic","addr:street":"Real street"},"geometry":{"type":"Point","coordinates":[32.01,54.78]}}]}""",MapGenerator.Generate(new(){Kind="blank"})).Project;var f=p.SourceFeatures.Single();Check(f.Kind=="poi"&&f.SourceGeometry[0][0].Longitude==32.01&&f.Tags["amenity"]=="clinic"&&f.Name=="Survey clinic","Source point lost");GeographicEvidence.Validate(p);Check(p.Buildings.Count==0,"POI invented a building");});
  yield return("OSM entrance evidence retains node identity and unsupported source roles",()=>{var p=GeographicImporter.Import("""{"elements":[{"type":"node","id":15,"lon":32.01,"lat":54.78,"tags":{"entrance":"no","access":"private","level":"1"}}]}""",MapGenerator.Generate(new(){Kind="blank"})).Project;var f=p.SourceFeatures.Single();Check(f.SourceId=="osm-node-15"&&f.Kind=="entrance"&&f.EntranceOutcome=="sealed"&&f.Tags["access"]=="private","Entrance role invented");});
  yield return("tiled node clipping retains selected POIs and deduplicates node IDs",()=>{var set=new OsmGeometrySet(100000);const string data="""{"elements":[{"type":"node","id":1,"lon":32.01,"lat":54.78,"tags":{"amenity":"school"}},{"type":"node","id":2,"lon":33,"lat":55,"tags":{"shop":"yes"}}]}""";set.Add(data);set.Add(data);using var doc=JsonDocument.Parse(set.ForSection(new(){West=32,East=32.02,South=54.77,North=54.79}));Check(doc.RootElement.GetProperty("elements").GetArrayLength()==1,"POI clipping or dedup failed");});
  yield return("geographic reimport preserves generation controls and zones",()=>{const string data="""{"elements":[{"type":"node","id":1,"lon":32.01,"lat":54.78,"tags":{"amenity":"school"}}]}""";var p=GeographicImporter.Import(data,MapGenerator.Generate(new(){Kind="blank"})).Project;p.Generation=new();var before=JsonSerializer.Serialize(p.Generation);var next=GeographicImporter.Import(data,p,p.Bounds,preserveEdits:true).Project;Check(JsonSerializer.Serialize(next.Generation)==before,"Generation controls dropped");});
 }
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
}
